    input clk,
    input reset,
    input write_enable,
    input [15:0] write_data,
    input [2:0] write_address,
    input [2:0] read_address1,
    input [2:0] read_address2,
    output [15:0] read_data1,
    output [15:0] read_data2
);

reg [15:0] registers [7:0];

