module fsm (
	input clk,
	input reset,
	input g,
	input h,
	output reg l);

	parameter V=0, W=1, S1=2, S2=3, S3=4;
	reg [2:0] state, next;

	always @(posedge clk) begin
		if (reset) state <= V;
		else state <= next;
	end

	always_comb begin
		case (state)
			V: next = g ? W : V;
			W: next = h ? S1 : S2;
			S1: next = h ? S2 : S3;
			S2: next = h ? S3 : V;
			S3: next = g ? W : V;
			default: next = 'x;
		endcase
	end

	assign l = (state == S2 && !h);

endmodule

