module garage_door_opener (
	input clk,
	input resetn,
	input button,
	output reg open);

	parameter CLOSED=0, OPENING=1, OPEN=2, CLOSING=3;
	reg [1:0] state, next_state;

	always @(posedge clk) begin
		if (~resetn) state <= CLOSED;
		else state <= next_state;
	end

	always_comb begin
		case (state)
			CLOSED: next_state = button ? OPENING : CLOSED;
			OPENING: next_state = OPEN;
			OPEN: next_state = button ? CLOSING : OPEN;
			CLOSING: next_state = CLOSED;
			default: next_state = CLOSED;
		endcase
	end

	always @(state) begin
		case (state)
			OPEN: open = 1;
			default: open = 0;
		endcase
	end
endmodule

