description:
Design a write-back multiplexer that selects one of four 32-bit input signals (muxin_a, muxin_b, muxin_c, muxin_d) based on the control signals from the rfwb_op input. The output (muxout) is determined by a 2-bit selection derived from rfwb_op, with an additional option that increments the selected input by 8. The module includes a clock and reset functionality, where the selected output is registered into muxreg on the positive edge of the clock if wb_freeze is not asserted. Additionally, a valid flag (muxreg_valid) indicates whether the write-back operation output is valid based on the least significant bit of rfwb_op.
module top_module(
    // Clock and reset
    clk, rst,

    // Internal i/f
    wb_freeze, rfwb_op,
    muxin_a, muxin_b, muxin_c, muxin_d,
    muxout, muxreg, muxreg_valid
);

code:
module top_module(
    // Clock and reset
    clk, rst,

    // Internal i/f
    wb_freeze, rfwb_op,
    muxin_a, muxin_b, muxin_c, muxin_d,
    muxout, muxreg, muxreg_valid
);parameter width = 32;

//
// I/O
//

//
// Clock and reset
//
input               clk;
input               rst;

//
// Internal i/f
//
input               wb_freeze;
input   [2:0]       rfwb_op;
input   [width-1:0] muxin_a;
input   [width-1:0] muxin_b;
input   [width-1:0] muxin_c;
input   [width-1:0] muxin_d;
output  [width-1:0] muxout;
output  [width-1:0] muxreg;
output              muxreg_valid;

//
// Internal wires and regs
//
reg [width-1:0] muxout;
reg [width-1:0] muxreg;
reg muxreg_valid;

//
// Registered output from the write-back multiplexer
//
always @(posedge clk or posedge rst) begin
    if (rst) begin
        muxreg <= 32'd0;
        muxreg_valid <= 1'b0;
    end
    else if (!wb_freeze) begin
        muxreg <= muxout;
        muxreg_valid <= rfwb_op[0];
    end
end

//
// Write-back multiplexer
//
always @(*) begin
    case(rfwb_op[2:1])
        2'b00: muxout = muxin_a;
        2'b01: muxout = muxin_b;
        2'b10: muxout = muxin_c;
        2'b11: muxout = muxin_d + 32'h8;
    endcase
end

endmodule

