module top_module(
  rst,
  wr_clk,
  rd_clk,
  din,
  wr_en,
  rd_en,
  dout,
  full,
  empty,
  prog_full
);parameter WIDTH = 256;
parameter DEPTH = 512;

input rst;
input wr_clk;
input rd_clk;
input [WIDTH-1 : 0] din;
input wr_en;
input rd_en;
output [WIDTH-1 : 0] dout;
output full;
output empty;
output prog_full;

reg [WIDTH-1 : 0] mem [0 : DEPTH-1];
reg [DEPTH-1 : 0] wr_ptr;
reg [DEPTH-1 : 0] rd_ptr;
wire [DEPTH-1 : 0] count = wr_ptr - rd_ptr;
wire [DEPTH-1 : 0] next_wr_ptr = wr_ptr + 1'b1;
wire [DEPTH-1 : 0] next_rd_ptr = rd_ptr + 1'b1;
wire [DEPTH-1 : 0] almost_full_threshold = DEPTH - 8;

assign full = (count == DEPTH);
assign empty = (count == 0);
assign prog_full = (count >= almost_full_threshold);

always @(posedge wr_clk or negedge rst) begin
  if (!rst) begin
    wr_ptr <= 0;
  end else if (wr_en && !full) begin
    wr_ptr <= next_wr_ptr;
    mem[wr_ptr] <= din;
  end
end

always @(posedge rd_clk or negedge rst) begin
  if (!rst) begin
    rd_ptr <= 0;
  end else if (rd_en && !empty) begin
    rd_ptr <= next_rd_ptr;
  end
end

assign dout = mem[rd_ptr];

endmodule

