module fsm (
	input clk,
	input reset,
	input r,
	input t,
	output reg u);

	parameter F=0, G=1, H1=2, H2=3, H3=4, H4=5, H5=6;
	reg [2:0] state, next;

	always @(posedge clk) begin
		if (reset) state <= F;
		else state <= next;
	end

	always_comb begin
		case (state)
			F: next = r ? G : F;
			G: next = t ? H1 : H2;
			H1: next = t ? H2 : H3;
			H2: next = t ? H3 : H4;
			H3: next = t ? H4 : H5;
			H4: next = r ? G : F;
			H5: next = r ? G : F;
			default: next = 'x;
		endcase
	end

	assign u = (state == H4 && !t);

endmodule

