module top_module(
    input CLK,
    input RESET,
    input VPWR,
    input VGND,
    output reg GREEN,
    output reg YELLOW,
    output reg RED
);parameter GREEN_TIME = 30_000_000; // 30 seconds
    parameter YELLOW_TIME = 5_000_000; // 5 seconds
    parameter RED_TIME = 25_000_000; // 25 seconds

    reg [23:0] counter;
    reg [1:0] state;

    always @(posedge CLK) begin
        if (RESET) begin
            counter <= 0;
            state <= 2'b00; // green state
        end
        else begin
            counter <= counter + 1;
            case (state)
                2'b00: begin // green state
                    GREEN <= 1;
                    YELLOW <= 0;
                    RED <= 0;
                    if (counter == GREEN_TIME) begin
                        counter <= 0;
                        state <= 2'b01; // yellow state
                    end
                end
                2'b01: begin // yellow state
                    GREEN <= 0;
                    YELLOW <= 1;
                    RED <= 0;
                    if (counter == YELLOW_TIME) begin
                        counter <= 0;
                        state <= 2'b10; // red state
                    end
                end
                2'b10: begin // red state
                    GREEN <= 0;
                    YELLOW <= 0;
                    RED <= 1;
                    if (counter == RED_TIME) begin
                        counter <= 0;
                        state <= 2'b00; // green state
                    end
                end
                default: begin
                    GREEN <= 0;
                    YELLOW <= 0;
                    RED <= 0;
                    counter <= 0;
                end
            endcase
        end
    end

endmodule

