We want to create a 4-bit synchronous counter that:

// (1) has a clock input 'clk',
// (2) has a reset input 'rst',
// (3) counts from 0 to 15 and wraps around to 0,
// (4) the counter resets to 0 when 'rst' is high.

module sync_counter(
    input wire clk,
    input wire rst,
    output reg [3:0] count
);

code:
module sync_counter(
    input wire clk,
    input wire rst,
    output reg [3:0] count
);

    always @(posedge clk) begin
        if (rst)
            count <= 4'b0000;
        else
            count <= count + 1;
    end

endmodule

