code:
module fsm_module (
        input clk,
        input reset,
        input trigger,
        output reg out);parameter X0=0, X1=1, X2=2, X3=3;
	reg[1:0] state, next;

	always @(posedge clk)
		if (reset) state <= X0;
		else state <= next;


	always_comb begin
		case (state)
			X0: next = trigger ? X1 : X0;
			X1: next = trigger ? X2 : X1;
			X2: next = trigger ? X3 : X2;
			X3: next = trigger ? X0 : X3;
			default: next = 'x;
		endcase
	end

	assign out = (state == X1) || (state == X3);

endmodule

