description:
Design a clock divider circuit that generates a slower clock (`update_clk`) based on a given input clock (`clk`). The module counts clock cycles and toggles `update_clk` to a HIGH state once the count reaches 4,000,000 cycles, effectively creating a 4 MHz output from a higher frequency input. The `update_clk` remains LOW until the threshold is reached, at which point it is set HIGH and the count resets.
module top_module(
input wire clk,
output reg update_clk
);

code:
module top_module(
input wire clk,
output reg update_clk
);reg [21:0] check;

    always @ (posedge clk) begin
        if(check < 4000000) begin
            check <= check + 1;
            update_clk <= 0;
        end
        else begin 
            check <= 0;
            update_clk <= 1;
        end
    end

endmodule

