  always @(posedge clock) begin 
  {a_,stall_} <= {a,stall}; 
  if (stall_ && a != a_) 
 $display("** %05d STALLCHECKER violation %d: was %x != now %x (%d)",$time, id, a_, a, stall_); 
  end 
 endmodule

module top_module(
   input      clk,
   input      reset_n,
   input      j,
   input      k,
   output reg q
   );always @(posedge clk, negedge reset_n)
     if (!reset_n)
       q <= 1'b0;
     else
       q <= (j & ~q) | (~k & q);

endmodule

