module top_module(
  input clk_in,
  input rst,
  output reg clk_out,
  output reg locked
);reg [31:0] count;
  reg [31:0] prev_count;
  reg locked_flag;

  always @(posedge clk_in) begin
    if (rst) begin
      count <= 0;
      prev_count <= 0;
      clk_out <= 0;
      locked_flag <= 0;
    end
    else begin
      count <= count + 1;
      if (count == 0) begin
        prev_count <= count;
        clk_out <= ~clk_out;
        if (prev_count != 0) begin
          locked_flag <= 1;
        end
      end
    end
  end

  always @(posedge clk_in) begin
    if (rst) begin
      locked <= 0;
    end
    else begin
      locked <= locked_flag;
    end
  end

endmodule

