					4'b0010:dm[A[12:2]][15:8]<=WD[7:0];
					4'b0100:dm[A[12:2]][23:16]<=WD[7:0];
					4'b1000:dm[A[12:2]][31:24]<=WD[7:0];
				endcase
			end
	end		
	if(rst==1)
	begin
		for(i=0;i<=1023;i=i+1)
			dm[i]<=0;
	end		
end
endmodule

