module top_module(wr_clk, wr_en, wr_data, rd_clk, rd_en, rd_data, empty, full);parameter WIDTH = 32;
  parameter DEPTH = 2048; // 8KB / 32 bits

  input wr_clk;
  input wr_en;
  input [WIDTH-1:0] wr_data;
  input rd_clk;
  input rd_en;
  output [WIDTH-1:0] rd_data;
  output empty;
  output full;

  reg [WIDTH-1:0] buffer [0:DEPTH-1];
  reg [WIDTH-1:0] rd_data_reg;
  reg [WIDTH-1:0] wr_data_reg;
  reg empty_reg;
  reg full_reg;
  integer wr_ptr_reg = 0;
  integer rd_ptr_reg = 0;

  always @(posedge wr_clk) begin
    if (wr_en && !full_reg) begin
      buffer[wr_ptr_reg] <= wr_data;
      wr_ptr_reg <= (wr_ptr_reg == DEPTH-1) ? 0 : wr_ptr_reg + 1;
      empty_reg <= 0;
      full_reg <= (wr_ptr_reg == rd_ptr_reg) ? 1 : 0;
    end
  end

  always @(posedge rd_clk) begin
    if (rd_en && !empty_reg) begin
      rd_data_reg <= buffer[rd_ptr_reg];
      rd_ptr_reg <= (rd_ptr_reg == DEPTH-1) ? 0 : rd_ptr_reg + 1;
      full_reg <= 0;
      empty_reg <= (rd_ptr_reg == wr_ptr_reg) ? 1 : 0;
    end
  end

  assign rd_data = rd_data_reg;
  assign empty = empty_reg;
  assign full = full_reg;

endmodule

