module top_module(rst, dout, dout_fabric, clk);// Added clk as an input for external clock signal

	////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
	// I/O declarations

	(* LOC = "P20" *)
	output wire dout;

	(* LOC = "P19" *)
	output wire dout_fabric;

	(* LOC = "P18" *)
	input wire rst;

	(* LOC = "P17" *) // This output location should be specified (if required)
	input wire clk; // External clock input

	////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
	// A hard IP counter

	localparam COUNT_MAX = 31;

	reg[7:0] count = COUNT_MAX;
	always @(posedge clk, posedge rst) begin // Changed to clk
		//level triggered reset
		if(rst)
			count			<= 0;

		//counter
		else begin
			if(count == 0)
				count		<= COUNT_MAX;
			else
				count		<= count - 1'd1;
		end
	end

	assign dout = (count == 0);

	////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
	// A fabric counter

	(* COUNT_EXTRACT = "NO" *)
	reg[5:0] count_fabric = COUNT_MAX; //TODO: run count_extract so we can do 7:0 and optimize
	always @(posedge clk, posedge rst) begin // Changed to clk
		//level triggered reset
		if(rst)
			count_fabric		<= 0;

		//counter
		else begin
			if(count_fabric == 0)
				count_fabric	<= COUNT_MAX;
			else
				count_fabric	<= count_fabric - 1'd1;
		end
	end

	assign dout_fabric = (count_fabric == 0);

endmodule

