description:
Design a circuit that functions as an active-low isolation gate. The output X is driven by input A when the SLEEP input is not asserted (active low), ensuring that when SLEEP is high, the output X is forced to a LOW state regardless of A, effectively isolating the output.
module top_module(
    X    ,
    A    ,
    SLEEP
);

code:
module top_module(
    X    ,
    A    ,
    SLEEP
);// Module ports
    output X    ;
    input  A    ;
    input  SLEEP;

    // Local signals
    wire sleepn;

    //  Name  Output  Other arguments
    not not0 (sleepn, SLEEP          );
    and and0 (X     , A, sleepn      );

endmodule

