module fsm (
  input in,
  input [1:0] state,
  output reg [1:0] next_state,
  output reg out);parameter A=0, B=1, C=2, D=3;

    always_comb begin
        case (state)
            A: next_state = in ? C : B;
            B: next_state = in ? D : A;
            C: next_state = in ? A : D;
            D: next_state = in ? B : C;
        endcase
    end

    assign out = (state==B) || (state==D);

endmodule

