	input reset,
	output reg [6:0] hours_display,
	output reg [6:0] minutes_display);reg [5:0] minutes;
	reg [4:0] hours;

	always @(posedge clk or posedge reset) begin
		if (reset) begin
			minutes <= 0;
			hours <= 0;
		end else begin
			if (minutes == 59) begin
				minutes <= 0;
				if (hours == 23) begin
					hours <= 0;
				end else begin
					hours <= hours + 1;
				end
			end else begin
				minutes <= minutes + 1;
			end
		end
